package com.example.rokidkeyboardbridge;
import org.json.*;
public class ConversationTraceTest {static int n;static void ok(boolean v){n++;if(!v)throw new AssertionError("trace "+n);}public static void main(String[] args)throws Exception{
 ConversationTrace.observe("{bad");ok(ConversationTrace.snapshot().length()==0);long a=ConversationTrace.begin("a".repeat(64),"image",300);ConversationTrace.observe("{bad");ok(!ConversationTrace.snapshot().optBoolean("responseObserved"));String raw=new JSONObject().put("candidates",new JSONArray().put(new JSONObject().put("finishReason","STOP").put("content",new JSONObject().put("private","do not retain")).put("groundingMetadata",new JSONObject().put("webSearchQueries",new JSONArray().put("private query")).put("groundingChunks",new JSONArray().put(new JSONObject().put("web",new JSONObject().put("uri","https://private.invalid/"))))))).toString();ConversationTrace.observe(raw);JSONObject trace=ConversationTrace.snapshot();ok(trace.optBoolean("responseObserved"));ok(trace.optBoolean("searchObserved"));ok(trace.optInt("queries")==1);ok(trace.optInt("sources")==1);ok(!trace.toString().contains("private"));ok(trace.optString("request").equals("a".repeat(64)));ConversationTrace.end(a,true);ok(ConversationTrace.snapshot().optString("phase").equals("RETURNED"));ConversationTrace.observe(raw);ok(ConversationTrace.snapshot().optInt("queries")==1);long b=ConversationTrace.begin("raw request must not be stored","bad",40);ok(ConversationTrace.snapshot().optString("request").isEmpty());ok(ConversationTrace.snapshot().optString("reference").equals("unknown"));ConversationTrace.observe("{\"candidates\":[{\"finishReason\":\"user secret\"}]}");ok(ConversationTrace.snapshot().optString("finishReason").equals("UNKNOWN"));ok(!ConversationTrace.snapshot().optBoolean("searchObserved"));ConversationTrace.end(b,false);ok(ConversationTrace.snapshot().optString("phase").equals("FAILED"));ok(!ConversationTrace.snapshot().toString().contains("user secret"));System.out.println("PASS content-free trace "+n);}}
